topics.codeExample:
import java.util.*;

public class ArrayVsCollectionComparison {
    public static void main(String[] args) {
        // 1. Primitive Array: Fixed capacity, manual shifting on delete
        String[] studentArray = new String[3];
        studentArray[0] = "Alice";
        studentArray[1] = "Bob";
        studentArray[2] = "Charlie";

        System.out.println("--- Array Storage (Fixed) ---");
        for (String name : studentArray) {
            System.out.println("Student: " + name);
        }

        // 2. Collection (List): Dynamic growth, rich built-in operations
        List<String> studentList = new ArrayList<>();
        studentList.add("Alice");
        studentList.add("Bob");
        studentList.add("Charlie");
        studentList.add("Diana"); // Dynamic expansion
        studentList.remove("Bob");  // O(N) shift handled automatically

        // 3. Utility Algorithms via Collections
        Collections.sort(studentList);

        System.out.println("\n--- ArrayList Storage (Dynamic & Sorted) ---");
        for (String name : studentList) {
            System.out.println("Student: " + name);
        }
        System.out.println("Contains Diana? " + studentList.contains("Diana"));
    }
}

