    public static void main(String[] args) {
        // Choosing ArrayList for primary record storage (frequent indexing)
        List<Student> roster = new ArrayList<>();
        roster.add(new Student(101, "Sarah Jenkins", 3.85));
        roster.add(new Student(102, "David Kim", 3.92));
        roster.add(new Student(103, "Elena Rostova", 3.74));

        // O(1) Fast lookup by index
        System.out.println("First registered student: " + roster.get(0));

        // Choosing LinkedList as a double-ended audit log (frequent head/tail additions)
        Deque<String> auditLog = new LinkedList<>();
        auditLog.addFirst("10:00 AM: User logged in");
        auditLog.addFirst("10:05 AM: Student 102 updated");
        auditLog.addLast("End of session audit marker");

        System.out.println("\nAudit Log (Recent First):");
        while (!auditLog.isEmpty()) {
            System.out.println("-> " + auditLog.pollFirst());
        }
    }
}

