topics.codeExample:
import java.util.*;

public class TextEditorUndoEngine {
    private final Deque<String> undoStack = new ArrayDeque<>();
    private final Deque<String> redoStack = new ArrayDeque<>();
    private String text = "";

    public void type(String newText) {
        undoStack.push(text); // snapshot current state
        redoStack.clear();
        text += newText;
    }

    public void undo() {
        if (!undoStack.isEmpty()) {
            redoStack.push(text);
            text = undoStack.pop();
        }
    }

    public void redo() {
        if (!redoStack.isEmpty()) {
            undoStack.push(text);
            text = redoStack.pop();
        }
    }

    public String getText() { return text; }

    public static void main(String[] args) {
        TextEditorUndoEngine editor = new TextEditorUndoEngine();
        editor.type("Hello");
        editor.type(" World");
        System.out.println("Current: '" + editor.getText() + "'");

        editor.undo();
        System.out.println("After Undo: '" + editor.getText() + "'");

        editor.redo();
        System.out.println("After Redo: '" + editor.getText() + "'");
    }
}

