public class StudentIdDirectory {
    public static void main(String[] args) {
        int[] inputIds = {503, 101, 204, 101, 408, 204, 109};

        // 1. HashSet: fast deduplication, arbitrary order
        Set<Integer> hashSet = new HashSet<>();
        // 2. LinkedHashSet: deduplication with insertion order
        Set<Integer> linkedHashSet = new LinkedHashSet<>();
        // 3. TreeSet: deduplication with natural sorted order
        NavigableSet<Integer> treeSet = new TreeSet<>();

