            hashSet.add(id);
            linkedHashSet.add(id);
            treeSet.add(id);
        }

        System.out.println("Input IDs count: " + inputIds.length);
        System.out.println("LinkedHashSet (Insertion order): " + linkedHashSet);
        System.out.println("TreeSet (Sorted order):          " + treeSet);
        System.out.println("TreeSet lowest:  " + treeSet.first());
        System.out.println("TreeSet highest: " + treeSet.last());
        System.out.println("TreeSet floor of 200: " + treeSet.floor(200));
    }
}

