import java.util.*;

public class StudentMarksManagementSystem {
    static class StudentScoreRecord {
        String studentName;
        double marks;

        StudentScoreRecord(String studentName, double marks) {
            this.studentName = studentName;
            this.marks = marks;
        }
        public String toString() { return studentName + " (" + marks + ")"; }
    }

    public static void main(String[] args) {
        // 1. HashMap for instant O(1) grade book lookup
        Map<String, StudentScoreRecord> gradeBook = new HashMap<>();
        gradeBook.put("STU-001", new StudentScoreRecord("Emma Watson", 94.5));
        gradeBook.put("STU-002", new StudentScoreRecord("Liam Neeson", 88.0));
        gradeBook.put("STU-003", new StudentScoreRecord("Sophia Loren", 98.2));

        System.out.println("Lookup STU-002: " + gradeBook.get("STU-002"));

        // 2. LinkedHashMap configured as a fixed-capacity (size 3) LRU Cache
        Map<String, String> recentSearches = new LinkedHashMap<>(4, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                return size() > 3; // Evicts oldest accessed when > 3
            }
        };

        recentSearches.put("Java", "Results for Java");
        recentSearches.put("Python", "Results for Python");
        recentSearches.put("C++", "Results for C++");
        // Accessing 'Java' moves it to the most-recently-used tail
        recentSearches.get("Java");
        // Adding 'Rust' causes eviction of 'Python' (the least recently used)
        recentSearches.put("Rust", "Results for Rust");

        System.out.println("\nLRU Cache Entries (Least to Most Recent):");
        for (String key : recentSearches.keySet()) {
            System.out.println("Cached Query: " + key);
        }
    }
}

