        employeeDir.put(1045, "Alice Smith (Engineering)");
        employeeDir.put(1012, "Bob Martin (Marketing)");
        employeeDir.put(1099, "Charlie Brown (Finance)");
        employeeDir.put(1025, "Diana Prince (Design)");

