        public String toString() { return name + " (Priority " + triagePriority + ")"; }
    }

    public static void main(String[] args) {
        // Comparator: primary by triagePriority, tie-breaker by arrivalOrder
        Comparator<Patient> triageComparator = Comparator
            .comparingInt((Patient p) -> p.triagePriority)
            .thenComparingLong(p -> p.arrivalOrder);

        PriorityQueue<Patient> erQueue = new PriorityQueue<>(triageComparator);

        erQueue.offer(new Patient("John (Flu)", 4, 1));
        erQueue.offer(new Patient("Sarah (Cardiac Alert)", 1, 2));
        erQueue.offer(new Patient("David (Sprained Ankle)", 3, 3));
        erQueue.offer(new Patient("Elena (Severe Trauma)", 1, 4));

        System.out.println("--- Emergency Room Patient Treatment Order ---");
        while (!erQueue.isEmpty()) {
            System.out.println("Treating: " + erQueue.poll());
        }
    }
}

