import java.util.*;

public class EmployeeSortAndTraversal {
    static class Employee implements Comparable<Employee> {
        int id;
        String name;
        double salary;

        Employee(int id, String name, double salary) {
            this.id = id;
            this.name = name;
            this.salary = salary;
        }

        // Natural order: by ID ascending
        @Override
        public int compareTo(Employee other) {
            return Integer.compare(this.id, other.id);
        }

        public double getSalary() { return salary; }
        public String toString() { return name + " [ID:" + id + ", $" + salary + "]"; }
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>();
        staff.add(new Employee(105, "Carlos", 75000));
        staff.add(new Employee(101, "Brenda", 92000));
        staff.add(new Employee(103, "Arthur", 64000));

        // 1. Natural Sort via Comparable (ID)
        Collections.sort(staff);
        System.out.println("Sorted by ID (Natural): " + staff);

        // 2. Custom Sort via Comparator (Salary Descending)
        staff.sort(Comparator.comparingDouble(Employee::getSalary).reversed());
        System.out.println("Sorted by Salary (Desc): " + staff);

        // 3. Bidirectional Traversal using ListIterator
        ListIterator<Employee> listIt = staff.listIterator(staff.size());
        System.out.println("\nBackward Traversal from End:");
        while (listIt.hasPrevious()) {
            int prevIndex = listIt.previousIndex();
            Employee emp = listIt.previous();
            System.out.println("Index " + prevIndex + ": " + emp.name);
        }
    }
}

