import java.util.*;

public class GenericDataRepository {
    // Generic Key-Value Pair container
    static class KeyValuePair<K, V> {
        private final K key;
        private final V value;

        public KeyValuePair(K key, V value) {
            this.key = key;
            this.value = value;
        }
        public K getKey() { return key; }
        public V getValue() { return value; }
        public String toString() { return key + " => " + value; }
    }

    // Bounded Generic Method: restricts T to subclasses of Number
    public static <T extends Number> double computeAverage(List<T> numbers) {
        if (numbers == null || numbers.isEmpty()) return 0.0;
        double total = 0.0;
        for (T num : numbers) {
            total += num.doubleValue(); // Safe access to Number methods
        }
        return total / numbers.size();
    }

    public static void main(String[] args) {
        KeyValuePair<Integer, String> entry = new KeyValuePair<>(101, "Active Session");
        System.out.println("Pair: " + entry);

        List<Integer> intList = Arrays.asList(10, 20, 30, 40);
