import java.util.*;

public class PecsTransferUtility {
    // PECS: Copies items from producer to consumer
    public static <T> void transfer(List<? extends T> source, List<? super T> destination) {
        for (T item : source) {
            destination.add(item);
        }
    }

    public static double sumOfNumbers(List<? extends Number> numbers) {
        double sum = 0;
        for (Number n : numbers) {
            sum += n.doubleValue();
        }
        return sum;
    }

    public static void main(String[] args) {
        List<Integer> sourceInts = Arrays.asList(10, 20, 30);
        List<Number> destinationNums = new ArrayList<>();

        // Transfer integers into number list using PECS
        transfer(sourceInts, destinationNums);
        System.out.println("Transferred Destination: " + destinationNums);

        // Calculate sum on both Integer and Double lists
        List<Double> doubles = Arrays.asList(2.5, 7.5);
        System.out.println("Sum of Ints:    " + sumOfNumbers(sourceInts));
        System.out.println("Sum of Doubles: " + sumOfNumbers(doubles));
    }
}

