public class UserValidationAndPipeline {
    static class User {
        String username;
        int age;
        String email;

        User(String username, int age, String email) {
            this.username = username;
            this.age = age;
            this.email = email;
        }
    }

    public static void main(String[] args) {
        // 1. Predicate Composition for Validation
        Predicate<User> isAdult = u -> u.age >= 18;
        Predicate<User> hasValidEmail = u -> u.email != null && u.email.contains("@");
        Predicate<User> canRegister = isAdult.and(hasValidEmail);

        // 2. Function for Data Transformation
        Function<User, String> formatProfile = u -> u.username.toUpperCase() + " (" + u.email + ")";

        // 3. Consumer for Output / Notification
        Consumer<String> notifier = profile -> System.out.println("Registered: " + profile);

        List<User> applicants = Arrays.asList(
            new User("alex", 22, "alex@domain.com"),
            new User("minor_sam", 15, "sam@domain.com"),
            new User("invalid_email_user", 25, "bademail")
        );

        for (User u : applicants) {
            if (canRegister.test(u)) {
                String profile = formatProfile.apply(u);
                notifier.accept(profile);
            } else {
                System.out.println("Rejected: " + u.username + " (failed validation)");
            }
        }
    }
}

