import java.util.*;
import java.util.stream.*;

public class DepartmentAnalyticsPipeline {
    static class Employee {
        String name;
        String dept;
        double salary;

        Employee(String name, String dept, double salary) {
            this.name = name; this.dept = dept; this.salary = salary;
        }
        public String getDept() { return dept; }
        public double getSalary() { return salary; }
        public String getName() { return name; }
    }

    public static void main(String[] args) {
        List<Employee> staff = Arrays.asList(
            new Employee("Alice", "Engineering", 120000),
            new Employee("Bob", "Marketing", 75000),
            new Employee("Charlie", "Engineering", 95000),
            new Employee("Diana", "Marketing", 85000),
            new Employee("Evan", "Engineering", 110000)
        );

        // 1. Grouping by Department with Average Salary
        Map<String, Double> deptAverages = staff.stream()
            .collect(Collectors.groupingBy(
                Employee::getDept,
                Collectors.averagingDouble(Employee::getSalary)
            ));

        System.out.println("--- Department Average Salaries ---");
        deptAverages.forEach((dept, avg) -> System.out.printf("%-12s: $%,.2f%n", dept, avg));

        // 2. Identify the single highest paid employee using reduce / maxBy
        Optional<Employee> topEarner = staff.stream()
            .max(Comparator.comparingDouble(Employee::getSalary));

        topEarner.ifPresent(e -> System.out.printf("\nHighest Paid: %s ($%,.2f)%n", e.getName(), e.getSalary()));

        // 3. Partitioning: High earners (>= 100k) vs standard
        Map<Boolean, List<String>> partitioned = staff.stream()
            .collect(Collectors.partitioningBy(
                e -> e.getSalary() >= 100000,
                Collectors.mapping(Employee::getName, Collectors.toList())
            ));

        System.out.println("\nEarners >= $100k: " + partitioned.get(true));
        System.out.println("Earners <  $100k: " + partitioned.get(false));
    }
}

