public class BankingTransactionService {
    // Custom Domain Checked Exception
    static class InsufficientBalanceException extends Exception {
        private final double shortfall;
        public InsufficientBalanceException(String msg, double shortfall) {
            super(msg);
            this.shortfall = shortfall;
        }
        public double getShortfall() { return shortfall; }
    }

    // Custom Technical Unchecked Exception
    static class PaymentGatewayException extends RuntimeException {
        public PaymentGatewayException(String msg, Throwable cause) {
            super(msg, cause);
        }
    }

    static class BankAccount {
        private double balance = 100.0;

        public void withdraw(double amount) throws InsufficientBalanceException {
            if (amount > balance) {
                throw new InsufficientBalanceException("Insufficient funds in account", amount - balance);
            }
            balance -= amount;
            System.out.println("Withdrew $" + amount + ", Remaining: $" + balance);
        }
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount();
        try {
            account.withdraw(150.0);
        } catch (InsufficientBalanceException e) {
            System.out.println("Transaction Denied: " + e.getMessage() + " (Shortfall: $" + e.getShortfall() + ")");
        } finally {
            System.out.println("Audit log updated: withdrawal attempt completed.");
        }
    }
}

