topics.codeExample:
import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class AnnotationValidationFramework {
    // 1. Custom Runtime Annotations
    @Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
    @interface NotNull {
        String message() default "Field must not be null";
    }

    @Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
    @interface Range {
        int min();
        int max();
    }

    // 2. Target Domain Class
    static class UserAccount {
        @NotNull(message = "Username is required")
        String username;

        @Range(min = 18, max = 100)
        int age;

        UserAccount(String username, int age) {
            this.username = username;
            this.age = age;
        }
    }

    // 3. Reflection-based Validator Engine
    public static List<String> validateEntity(Object target) throws IllegalAccessException {
        List<String> errors = new ArrayList<>();
        Class<?> clazz = target.getClass();

        for (Field f : clazz.getDeclaredFields()) {
            f.setAccessible(true);
            Object value = f.get(target);

            if (f.isAnnotationPresent(NotNull.class) && value == null) {
                errors.add(f.getAnnotation(NotNull.class).message());
            }

            if (f.isAnnotationPresent(Range.class) && value instanceof Integer) {
                Range r = f.getAnnotation(Range.class);
                int val = (Integer) value;
                if (val < r.min() || val > r.max()) {
                    errors.add(f.getName() + " out of range [" + r.min() + " - " + r.max() + "]: " + val);
                }
            }
        }
        return errors;
    }

    public static void main(String[] args) throws Exception {
        UserAccount validUser = new UserAccount("john_doe", 25);
        UserAccount invalidUser = new UserAccount(null, 15);

        System.out.println("Valid User Errors:   " + validateEntity(validUser));
        System.out.println("Invalid User Errors: " + validateEntity(invalidUser));
    }
}

