import java.util.*;

public class ConcurrentFileDownloader {
    static class DownloadTask implements Runnable {
        private final String fileName;
        private final int durationMillis;

        public DownloadTask(String fileName, int durationMillis) {
            this.fileName = fileName;
            this.durationMillis = durationMillis;
        }

        @Override
        public void run() {
            System.out.println("[" + Thread.currentThread().getName() + "] Starting download: " + fileName);
            try {
                Thread.sleep(durationMillis);
            } catch (InterruptedException e) {
                System.err.println("Download interrupted: " + fileName);
                Thread.currentThread().interrupt(); // Restore interrupted status
            }
            System.out.println("[" + Thread.currentThread().getName() + "] Finished: " + fileName);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        System.out.println("Main thread initiating parallel downloads...");

        Thread t1 = new Thread(new DownloadTask("Dataset_A.zip", 150), "Downloader-1");
        Thread t2 = new Thread(new DownloadTask("Model_Weights.bin", 100), "Downloader-2");

        long start = System.currentTimeMillis();
        t1.start();
        t2.start();

        // Wait for both threads to conclude
        t1.join();
        t2.join();

        long elapsed = System.currentTimeMillis() - start;
        System.out.println("All downloads complete in ~" + elapsed + "ms (Concurrent execution)");
    }
}

