import java.util.concurrent.atomic.AtomicInteger;

public class ThreadSafeBankAccount {
    static class BankAccount {
        private double balance = 1000.0;
        private final Object lock = new Object();

        // Synchronized block ensures only one thread updates balance at a time
        public void withdraw(double amount) {
            synchronized (lock) {
                if (balance >= amount) {
                    try { Thread.sleep(10); } catch (InterruptedException ignored) {}
                    balance -= amount;
                    System.out.printf("[%s] Withdrew $%.2f | Balance: $%.2f%n",
                        Thread.currentThread().getName(), amount, balance);
                } else {
                    System.out.printf("[%s] Overdraft Denied! Balance: $%.2f%n",
                        Thread.currentThread().getName(), balance);
                }
            }
        }
        public double getBalance() { synchronized (lock) { return balance; } }
    }

    public static void main(String[] args) throws InterruptedException {
        BankAccount account = new BankAccount();

        // Spawn two threads attempting to withdraw $600 simultaneously from $1000 balance
        Thread t1 = new Thread(() -> account.withdraw(600.0), "ATM-Branch-1");
        Thread t2 = new Thread(() -> account.withdraw(600.0), "Mobile-App-2");

        t1.start();
        t2.start();

        t1.join();
        t2.join();

