import java.util.*;
import java.util.concurrent.*;

public class BatchReportProcessor {
    static class ReportTask implements Callable<String> {
        private final int reportId;

        public ReportTask(int reportId) { this.reportId = reportId; }

        @Override
        public String call() throws Exception {
            long start = System.currentTimeMillis();
            Thread.sleep(50); // Simulate computation
            return "Report #" + reportId + " generated by " + Thread.currentThread().getName();
        }
    }

    public static void main(String[] args) {
        // Fixed pool matching CPU cores
        int cores = 3;
        ExecutorService pool = Executors.newFixedThreadPool(cores);
        List<Future<String>> futures = new ArrayList<>();

        // Dispatch 5 report generation jobs across 3 threads
        for (int i = 1; i <= 5; i++) {
            futures.add(pool.submit(new ReportTask(i)));
        }

        // Harvest results from futures
        for (Future<String> f : futures) {
            try {
                System.out.println("Result: " + f.get(1, TimeUnit.SECONDS));
            } catch (Exception e) {
                System.err.println("Task failed: " + e.getMessage());
            }
        }

        // Graceful pool shutdown
        pool.shutdown();
        try {
            if (!pool.awaitTermination(2, TimeUnit.SECONDS)) pool.shutdownNow();
        } catch (InterruptedException e) {
            pool.shutdownNow();
        }
        System.out.println("Report batch processing concluded.");
    }
}

