        String userId = "USR-901";
        long start = System.currentTimeMillis();

        CompletableFuture<UserProfile> profileFuture = fetchProfileAsync(userId);
        CompletableFuture<CreditScore> creditFuture = fetchCreditScoreAsync(userId);

        // Combine both independent microservice responses in parallel
        CompletableFuture<String> summaryFuture = profileFuture.thenCombine(
            creditFuture,
            (profile, credit) -> String.format("Client %s [%s] - Credit Rating: %d",
                profile.name, profile.id, credit.score)
