import java.util.concurrent.*;

public class ProducerConsumerPipeline {
    public static void main(String[] args) throws InterruptedException {
        // Bounded buffer holding at most 2 items
        BlockingQueue<Integer> buffer = new ArrayBlockingQueue<>(2);

        // Producer Thread: generates numbers
        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= 3; i++) {
                    System.out.println("[Producer] Producing: " + i);
                    buffer.put(i); // Blocks if buffer is full
                    Thread.sleep(30);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "Producer-Worker");

        // Consumer Thread: processes numbers
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 1; i <= 3; i++) {
                    int value = buffer.take(); // Blocks if buffer is empty
                    System.out.println("   [Consumer] Consumed: " + value);
                    Thread.sleep(60); // Slower consumer
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "Consumer-Worker");

        producer.start();
        consumer.start();

        producer.join();
        consumer.join();
        System.out.println("Pipeline processing complete.");
    }
}

