import java.util.*;

public class MemoryLeakAnalysis {
    // Antipattern: Static collection acts as an accidental GC Root
    static class LeakyCacheManager {
        private static final List<byte[]> leakedObjects = new ArrayList<>();
        public static void cacheData(byte[] payload) {
            leakedObjects.add(payload); // Accidental permanent heap retention!
        }
        public static void clear() { leakedObjects.clear(); }
        public static int size() { return leakedObjects.size(); }
    }

    public static void main(String[] args) {
        Runtime rt = Runtime.getRuntime();
        long initialFree = rt.freeMemory();
        System.out.println("Initial Free Heap: " + (initialFree / (1024 * 1024)) + " MB");

        // Simulate memory allocation
        for (int i = 0; i < 5; i++) {
            LeakyCacheManager.cacheData(new byte[1024 * 1024]); // 1MB chunks
        }
        System.out.println("Cached chunks count: " + LeakyCacheManager.size());
        long afterAllocFree = rt.freeMemory();
        System.out.println("Free Heap after allocation: " + (afterAllocFree / (1024 * 1024)) + " MB");

        // Proper cleanup removes GC root references
        LeakyCacheManager.clear();
        System.gc();
        System.out.println("Cleanup executed successfully. GC root severed.");
    }
}

