public class PerformanceComparisonDemo {
    public static void main(String[] args) {
        int iterations = 10000;

        // 1. String Concatenation vs StringBuilder
        long t0 = System.nanoTime();
        String s = "";
        for (int i = 0; i < iterations; i++) {
            s += "A";
        }
        long t1 = System.nanoTime();
        long concatDuration = (t1 - t0) / 1_000_000;

        long t2 = System.nanoTime();
        StringBuilder sb = new StringBuilder(iterations);
        for (int i = 0; i < iterations; i++) {
            sb.append("A");
        }
        String sbResult = sb.toString();
        long t3 = System.nanoTime();
        long sbDuration = (t3 - t2) / 1_000_000;

        System.out.println("String += loop (10k items):   ~" + concatDuration + " ms");
        System.out.println("StringBuilder (10k items):     ~" + sbDuration + " ms (Orders of magnitude faster)");

        // 2. Autoboxing vs Primitive Performance
        long t4 = System.nanoTime();
        long primitiveSum = 0L;
        for (long i = 0; i < 1_000_000L; i++) {
            primitiveSum += i;
        }
        long t5 = System.nanoTime();
        long primDuration = (t5 - t4) / 1_000_000;
        System.out.println("Primitive sum (1M items):      ~" + primDuration + " ms (Sum: " + primitiveSum + ")");
    }
}

