import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

public class ConcurrentTaskManagerApp {
    public enum TaskPriority { CRITICAL(1), HIGH(2), MEDIUM(3), LOW(4); int level; TaskPriority(int l) { level = l; } }

    public record Task(String id, String title, String category, TaskPriority priority, int durationMs) {}

    static class InvalidTaskException extends Exception {
        public InvalidTaskException(String msg) { super(msg); }
    }

    private final PriorityQueue<Task> pendingQueue = new PriorityQueue<>(Comparator.comparingInt(t -> t.priority.level));
    private final ConcurrentMap<String, String> statusMap = new ConcurrentHashMap<>();
    private final AtomicInteger completedCount = new AtomicInteger(0);
    private final ExecutorService executor;
    private final List<Task> allTasks = new ArrayList<>();

    public ConcurrentTaskManagerApp(int workerThreads) {
        this.executor = Executors.newFixedThreadPool(workerThreads);
    }

    public synchronized void addTask(Task task) throws InvalidTaskException {
        if (task.id == null || task.id.isBlank()) throw new InvalidTaskException("Task ID required");
        if (task.durationMs <= 0) throw new InvalidTaskException("Duration must be > 0");
        pendingQueue.offer(task);
        allTasks.add(task);
        statusMap.put(task.id, "PENDING");
    }

    public CompletableFuture<Void> runAllTasksAsync() {
        List<CompletableFuture<Void>> futures = new ArrayList<>();
        synchronized (this) {
            while (!pendingQueue.isEmpty()) {
                Task task = pendingQueue.poll();
                CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
                    statusMap.put(task.id, "RUNNING");
                    try { Thread.sleep(task.durationMs); } catch (InterruptedException ignored) {}
                    statusMap.put(task.id, "COMPLETED");
                    completedCount.incrementAndGet();
                    System.out.printf("[%s] Completed Task: %s (%s)%n",
                        Thread.currentThread().getName(), task.title, task.priority);
                }, executor);
                futures.add(future);
            }
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));
    }

    public Map<String, Long> getTaskCountByCategory() {
        return allTasks.stream().collect(Collectors.groupingBy(Task::category, Collectors.counting()));
    }

    public void exportReport(Path path) throws IOException {
        StringBuilder sb = new StringBuilder();
        sb.append("=== CONCURRENT TASK REPORT ===\n");
        sb.append("Total Completed: ").append(completedCount.get()).append("\n");
        sb.append("Category Breakdown: ").append(getTaskCountByCategory()).append("\n");
        Files.writeString(path, sb.toString());
    }

    public void shutdown() {
        executor.shutdown();
    }

    public static void main(String[] args) throws Exception {
        ConcurrentTaskManagerApp app = new ConcurrentTaskManagerApp(3);
        app.addTask(new Task("T1", "Payment Gateway Healthcheck", "FinTech", TaskPriority.CRITICAL, 60));
        app.addTask(new Task("T2", "Weekly Sales Aggregation", "Analytics", TaskPriority.MEDIUM, 40));
        app.addTask(new Task("T3", "Zero-Day Patch Deployment", "Security", TaskPriority.CRITICAL, 50));
        app.addTask(new Task("T4", "User Email Dispatch", "Marketing", TaskPriority.LOW, 20));

        System.out.println("Dispatched 4 tasks across 3 worker threads...");
        app.runAllTasksAsync().join();

        System.out.println("\nAnalytics by Category: " + app.getTaskCountByCategory());
        Path reportPath = Path.of("task_summary.txt");
        app.exportReport(reportPath);
        System.out.println("Report successfully written to: " + reportPath.getFileName());
        Files.deleteIfExists(reportPath);
        app.shutdown();
    }
}

